  it("ignores open prop", () => {
    renderLightbox({ open: false });

    testMainScenario();
  });

  it("doesn't close", () => {
    const close = vi.fn();
    const ref = React.createRef<ControllerRef>();

    renderLightbox({ controller: { ref }, close });

    ref.current!.close();

    expect(close).not.toHaveBeenCalled();

    testMainScenario();
  });
